#!/usr/bin/env bash
# Install estack into Codex / pi / omp and verify the go skill + scripts are visible.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
PASS=0
FAIL=0

ok() { PASS=$((PASS + 1)); echo "PASS  $*"; }
bad() { FAIL=$((FAIL + 1)); echo "FAIL  $*"; }

echo "== build entry skills =="
python3 "$ROOT/scripts/build_entry_skills.py"
if grep -q "Generated by scripts/build_entry_skills.py" "$ROOT/skills/go/SKILL.md"; then
  ok "go/SKILL.md generated"
else
  bad "go/SKILL.md missing generated banner"
fi
if [[ -f "$ROOT/skills/poteto-mode/SKILL.md" ]]; then
  ok "poteto-mode skill present"
else
  bad "missing skills/poteto-mode/SKILL.md (run scripts/port_pstack.py)"
fi
if grep -q "Generated by scripts/build_entry_skills.py" "$ROOT/agents/v-agent.md"; then
  ok "v-agent.md generated"
else
  bad "v-agent.md missing generated banner"
fi

echo "== fallback unit tests =="
if python3 "$ROOT/scripts/test_fallbacks.py"; then
  ok "test_fallbacks.py"
else
  bad "test_fallbacks.py"
fi

echo "== package.json pi.skills =="
if python3 -c "import json; p=json.load(open('$ROOT/package.json')); assert './skills' in p['pi']['skills']"; then
  ok "package.json declares pi.skills"
else
  bad "package.json pi.skills"
fi

# --- pi ---
if command -v pi >/dev/null 2>&1; then
  echo "== pi install =="
  if pi install "$ROOT" --no-approve 2>&1 | tee /tmp/estack-pi-install.log; then
    ok "pi install"
  else
    # re-install / already present can still be fine
    if rg -qi 'already|installed|added|estack' /tmp/estack-pi-install.log; then
      ok "pi install (already present)"
    else
      bad "pi install"
      cat /tmp/estack-pi-install.log
    fi
  fi
  if pi list 2>/dev/null | tee /tmp/estack-pi-list.log | rg -q 'estack|Skill Factory/estack'; then
    ok "pi list shows estack"
  else
    # settings packages may use relative path
    if rg -q 'estack' "$HOME/.pi/agent/settings.json" 2>/dev/null; then
      ok "pi settings.json references estack"
    else
      bad "pi list/settings missing estack"
      cat /tmp/estack-pi-list.log || true
    fi
  fi
  # skill file reachable from package path
  if [[ -f "$ROOT/skills/go/SKILL.md" ]]; then
    ok "pi can resolve skills/go/SKILL.md on disk"
  fi
else
  bad "pi binary not found"
fi

# --- omp ---
if command -v omp >/dev/null 2>&1; then
  echo "== omp plugin install =="
  if omp plugin install "$ROOT" --force 2>&1 | tee /tmp/estack-omp-install.log; then
    ok "omp plugin install"
  else
    if omp plugin link "$ROOT" --force 2>&1 | tee /tmp/estack-omp-link.log; then
      ok "omp plugin link"
    else
      bad "omp plugin install/link"
      cat /tmp/estack-omp-install.log /tmp/estack-omp-link.log 2>/dev/null || true
    fi
  fi
  if omp plugin list 2>&1 | tee /tmp/estack-omp-list.log | rg -qi 'estack'; then
    ok "omp plugin list shows estack"
  else
    bad "omp plugin list missing estack"
    cat /tmp/estack-omp-list.log || true
  fi
else
  bad "omp binary not found"
fi

# --- codex ---
if command -v codex >/dev/null 2>&1; then
  echo "== codex marketplace + plugin =="
  if [[ ! -f "$ROOT/.agents/plugins/marketplace.json" ]]; then
    bad "missing .agents/plugins/marketplace.json"
  else
    ok ".agents/plugins/marketplace.json present"
  fi
  if codex plugin marketplace add "$ROOT" --json 2>&1 | tee /tmp/estack-codex-mkt.log; then
    ok "codex marketplace add"
  else
    if rg -qi 'already|estack-local|exists' /tmp/estack-codex-mkt.log; then
      ok "codex marketplace add (existing)"
    else
      bad "codex marketplace add"
      cat /tmp/estack-codex-mkt.log
    fi
  fi
  if codex plugin add "estack@estack-local" --json 2>&1 | tee /tmp/estack-codex-add.log; then
    ok "codex plugin add estack@estack-local"
  else
    if rg -qi 'already|installed|enabled' /tmp/estack-codex-add.log; then
      ok "codex plugin add (already installed)"
    else
      bad "codex plugin add"
      cat /tmp/estack-codex-add.log
    fi
  fi
  if codex plugin marketplace list --json 2>/dev/null | rg -q 'estack-local'; then
    ok "codex marketplace list has estack-local"
  else
    bad "codex marketplace list missing estack-local"
  fi
  if codex plugin list 2>/dev/null | rg -i 'estack@estack-local' >/tmp/estack-codex-list.log; then
    ok "codex plugin list shows estack@estack-local"
  elif find "$HOME/.codex/plugins" -iname '*estack*' 2>/dev/null | head -1 | rg -q .; then
    ok "codex plugins cache contains estack"
  elif rg -q 'estack@estack-local' "$HOME/.codex/config.toml" 2>/dev/null; then
    ok "codex config.toml enables estack@estack-local"
  else
    bad "codex missing estack in list/cache/config"
    head -20 /tmp/estack-codex-list.log || true
  fi
else
  bad "codex binary not found"
fi

echo
echo "$PASS passed, $FAIL failed"
exit "$([[ "$FAIL" -eq 0 ]] && echo 0 || echo 1)"
